"use strict";let printDetails=[];window.addEventListener("beforeprint",()=>{printDetails=Array.from(document.querySelectorAll("details"),e=>({element:e,open:e.open})),printDetails.forEach(({element:e})=>{e.open=!0})}),window.addEventListener("afterprint",()=>{printDetails.forEach(({element:e,open:t})=>{e.open=t}),printDetails=[]}),document.querySelectorAll("[data-print]").forEach(e=>{e.hidden=!1,e.addEventListener("click",()=>window.print())});
